body {
  margin: 0;
  font-family: Arial;
  background-color: rgba(3, 21, 38, 1);
  color: white;

  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Navbar */
.navbar {
  display: flex;
  justify-content: space-between;
  padding: 15px 30px;
  background-color: #02101f;
}

.nav-item, .logo {
  color: white;
  text-decoration: none;
  margin-left: 15px;
}

/* Footer */
.footer {
  text-align: center;
  padding: 2px;
  background-color: #02101f;
  margin-top: 300px;
}


.puzzle{
  position: relative;
  height: 500px;
   margin-top: -80px;
}

/* الصورة */
.puzzle-img {
  position: absolute;
  right: 25px;   /* تتحكم في يمين/شمال */
  top: 300px;     /* تتحكم في فوق/تحت */
  width: 300px;
}

/* الكلام */
.text {
  position: absolute;
  right: 80px;   /* حركي الرقم عشان تغيري مكانه */
  top: 300px;
  color: orange;
}

